using Microsoft.Data.SqlClient;using System;using System.Data;using System.Windows;using System.Windows.Controls;
namespace POSS{public partial class SalesHistoryPage:Page{private readonly string connectionString=DatabaseConfig.ConnectionString;public SalesHistoryPage(){InitializeComponent();LoadSales();LoadDashboard();}
private void LoadSales(string keyword=""){try{using SqlConnection conn=new(connectionString);conn.Open();SqlDataAdapter da=new("SELECT ProductName,Price,Qty,Total,SaleDate FROM Sales WHERE ProductName LIKE @Keyword ORDER BY SaleDate DESC",conn);da.SelectCommand.Parameters.AddWithValue("@Keyword","%"+keyword+"%");DataTable dt=new();da.Fill(dt);HistoryGrid.ItemsSource=dt.DefaultView;}catch(Exception ex){MessageBox.Show(ex.Message);}}
private void LoadDashboard(){try{using SqlConnection conn=new(connectionString);conn.Open();txtTodaySales.Text=$"¥{Convert.ToInt32(new SqlCommand("SELECT ISNULL(SUM(Total),0) FROM Sales WHERE CAST(SaleDate AS DATE)=CAST(GETDATE() AS DATE)",conn).ExecuteScalar()):N0}";txtMonthSales.Text=$"¥{Convert.ToInt32(new SqlCommand("SELECT ISNULL(SUM(Total),0) FROM Sales WHERE YEAR(SaleDate)=YEAR(GETDATE()) AND MONTH(SaleDate)=MONTH(GETDATE())",conn).ExecuteScalar()):N0}";txtGrandSales.Text=$"¥{Convert.ToInt32(new SqlCommand("SELECT ISNULL(SUM(Total),0) FROM Sales",conn).ExecuteScalar()):N0}";}catch(Exception ex){MessageBox.Show(ex.Message);}}
private void btnSearch_Click(object sender,RoutedEventArgs e){LoadSales(txtSearch.Text);LoadDashboard();}private void btnAll_Click(object sender,RoutedEventArgs e){txtSearch.Clear();LoadSales();LoadDashboard();}private void btnToday_Click(object sender,RoutedEventArgs e){try{using SqlConnection conn=new(connectionString);conn.Open();SqlDataAdapter da=new("SELECT ProductName,Price,Qty,Total,SaleDate FROM Sales WHERE CAST(SaleDate AS DATE)=CAST(GETDATE() AS DATE) ORDER BY SaleDate DESC",conn);DataTable dt=new();da.Fill(dt);HistoryGrid.ItemsSource=dt.DefaultView;LoadDashboard();}catch(Exception ex){MessageBox.Show(ex.Message);}}}}